    const commitResult = await runGit2(["-C", sourcePath, "rev-parse", "HEAD"]);
    const commit = commitResult.stdout.trim();
    if (!/^[a-f0-9]{40,64}$/u.test(commit)) throw new Error("Invalid Git SHA.");
